def validate_code(code):
    if not isinstance(code, str):
        return False
    if not code.startswith("INV-"):
        return False
    tail = code[4:]
    if len(tail) != 4:
        return False
    return tail.isdigit()

def tier_of(rank):
    if not isinstance(rank, int) or isinstance(rank, bool):
        return "invalid"
    if rank < 1:
        return "invalid"
    if rank <= 3:
        return "bronze"
    if rank <= 6:
        return "silver"
    if rank <= 9:
        return "gold"
    return "platinum"

def check_entry(entry):
    if not isinstance(entry, dict):
        return "bad"
    if entry.get("sealed"):
        return "sealed"
    code = entry.get("code")
    rank = entry.get("rank")
    if not validate_code(code):
        return "bad"
    tier = tier_of(rank)
    if tier == "invalid":
        return "bad"
    if tier == "platinum":
        return "review"
    return "ok"
